const WebSocket = require('ws');
const http = require('http');
const crypto = require('crypto');

class TenantRegistry {
  constructor() {
    this.tenants = new Map();
    this.sessions = new Map();
  }

  registerTenant(tenantId, config) {
    this.tenants.set(tenantId, {
      id: tenantId,
      allowedOrigins: config.origins || [],
      maxConnections: config.maxConnections || 100,
      headerPolicy: config.headerPolicy || 'strict'
    });
  }

  validateSession(token) {
    return this.sessions.get(token) || null;
  }

  createSession(tenantId, userId) {
    const token = crypto.randomBytes(32).toString('hex');
    this.sessions.set(token, { tenantId, userId, created: Date.now() });
    return token;
  }
}

class MessageRouter {
  constructor(registry) {
    this.registry = registry;
    this.channels = new Map();
  }

  formatProtocolMessage(action, tenantId, payload) {
    const tenant = this.registry.tenants.get(tenantId);
    const separator = this.getFieldSeparator(tenant);
    const header = `X-Tenant-Id: ${tenantId}${separator}X-Action: ${action}`;
    const body = typeof payload === 'string' ? payload : JSON.stringify(payload);
    return `${header}${separator}${separator}${body}`;
  }

  getFieldSeparator(tenant) {
    if (!tenant) return '\n';
    switch (tenant.headerPolicy) {
      case 'strict': return '\n';
      case 'legacy': return '\r\n';
      default: return '\n';
    }
  }

  parseIncomingMessage(raw, tenantId) {
    const tenant = this.registry.tenants.get(tenantId);
    const separator = this.getFieldSeparator(tenant);
    const parts = raw.split(separator + separator);
    if (parts.length < 2) return null;

    const headerSection = parts[0];
    const body = parts.slice(1).join(separator + separator);
    const headers = {};

    headerSection.split(separator).forEach(line => {
      const colonIdx = line.indexOf(':');
      if (colonIdx > 0) {
        const key = line.substring(0, colonIdx).trim();
        const value = line.substring(colonIdx + 1).trim();
        headers[key.toLowerCase()] = value;
      }
    });

    return { headers, body };
  }

  routeMessage(ws, tenantId, message) {
    const parsed = this.parseIncomingMessage(message, tenantId);
    if (!parsed) {
      ws.send(this.formatProtocolMessage('error', tenantId, { error: 'malformed' }));
      return;
    }

    const targetChannel = parsed.headers['x-channel'];
    const action = parsed.headers['x-action'] || 'broadcast';

    if (targetChannel && this.isChannelAuthorized(tenantId, targetChannel)) {
      this.deliverToChannel(targetChannel, tenantId, action, parsed.body);
    }
  }

  isChannelAuthorized(tenantId, channel) {
    return channel.startsWith(`${tenantId}/`);
  }

  deliverToChannel(channel, tenantId, action, body) {
    const subscribers = this.channels.get(channel) || [];
    const outMsg = this.formatProtocolMessage(action, tenantId, body);
    subscribers.forEach(ws => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(outMsg);
      }
    });
  }

  subscribe(channel, ws) {
    if (!this.channels.has(channel)) {
      this.channels.set(channel, new Set());
    }
    this.channels.get(channel).add(ws);
  }
}

class SecureWebSocketServer {
  constructor(port) {
    this.registry = new TenantRegistry();
    this.router = new MessageRouter(this.registry);

    this.registry.registerTenant('tenant-alpha', {
      origins: ['https://alpha.example.com'],
      headerPolicy: 'legacy',
      maxConnections: 50
    });
    this.registry.registerTenant('tenant-beta', {
      origins: ['https://beta.example.com'],
      headerPolicy: 'strict',
      maxConnections: 200
    });

    this.server = http.createServer();
    this.wss = new WebSocket.Server({ server: this.server });

    this.wss.on('connection', (ws, req) => this.handleConnection(ws, req));
    this.server.listen(port);
  }

  handleConnection(ws, req) {
    const token = this.extractToken(req);
    const session = this.registry.validateSession(token);
    if (!session) {
      ws.close(4001, 'Unauthorized');
      return;
    }

    ws.tenantId = session.tenantId;
    ws.userId = session.userId;

    ws.on('message', (data) => {
      const message = data.toString('utf-8');
      if (this.validateMessageBoundary(message, ws.tenantId)) {
        this.router.routeMessage(ws, ws.tenantId, message);
      }
    });
  }

  validateMessageBoundary(message, tenantId) {
    const tenant = this.registry.tenants.get(tenantId);
    if (!tenant) return false;

    if (tenant.headerPolicy === 'strict') {
      if (message.includes('\r\n')) return false;
    }

    const maxLen = 65536;
    if (message.length > maxLen) return false;

    return true;
  }

  extractToken(req) {
    const url = new URL(req.url, `http://${req.headers.host}`);
    return url.searchParams.get('token') || '';
  }
}

module.exports = { SecureWebSocketServer, TenantRegistry, MessageRouter };
